      console.log(JSON.stringify({
        timestamp: new Date().toISOString(),
        method: req.method,
        path: req.path,
        status: res.statusCode,
        duration_ms: Date.now() - start,
        user_id: req.user?.id
      }));
    }
    return originalEnd.call(this, ...args);
  };

  next();
});

