const express = require("express");
const db = require("../db");

const router = express.Router();

router.post("/", async (req, res) => {
  const idempotencyKey = req.get('Idempotency-Key');
  if (!idempotencyKey) return res.status(400).json({ error: "Idempotency-Key header required" });

  const existing = await db.query(
    "SELECT * FROM orders WHERE account_id = $1 AND idempotency_key = $2",
    [req.user.accountId, idempotencyKey]
  );
  if (existing.length) return res.status(201).json(existing[0]);

  const row = await db.write(
    "INSERT INTO orders (account_id, sku, quantity, idempotency_key) VALUES ($1, $2, $3, $4) RETURNING *",
    [req.user.accountId, req.body.sku, req.body.quantity, idempotencyKey]
  );
  res.status(201).json(row);
});

router.patch("/:id/cancel", async (req, res) => {
  const row = await db.write(
    "UPDATE orders SET status = 'cancelled' WHERE id = $1 AND account_id = $2 RETURNING *",
    [req.params.id, req.user.accountId]
  );
  if (!row.length) return res.status(403).end();
  res.json(row[0]);
});

module.exports = router;

turns.text:
The connection drop causes a cascading failure:

1. A query (BEGIN, the actual query, or COMMIT) throws when the connection dies.
2. The catch block tries `client.query("ROLLBACK")` on a connection that's already dead.
3. That ROLLBACK also throws, replacing the original error.
4. The finally block calls `client.release()` on the dead connection (might fail silently or throw).
5. The caller receives a ROLLBACK error instead of knowing the connection dropped.

The transaction is lost — PostgreSQL automatically rolls back the transaction when the connection closes, but the client doesn't know that happened cleanly. If you want to handle this correctly, catch and suppress ROLLBACK errors so the original connection error surfaces:

```javascript
catch (err) {
  try {
    await client.query("ROLLBACK");
  } catch (rollbackErr) {
    // connection already dead, ignore
  }
  throw err;
}
```
